+
+function safeOuterShadow(colorHex, opacity, angle, blur, distance) {
+  return {
+    type: 'outer',
+    color: colorHex,
+    opacity: Math.max(0, Math.min(1, opacity)),
+    angle,
+    blur,
+    distance
+  };
+}
+
+function calcTextBoxHeight(fontSizePt, lineCount, lineSpacing = 1.2) {
+  // Very small helper for consistent box sizing.
+  return (fontSizePt / 72) * lineCount * lineSpacing;
+}
